mapper.select:
SELECT e.id, e.trip_id, e.author_id, e.content, e.intensity, e.advice, e.created_at, e.updated_at
  FROM trip_experiences e
  JOIN trip_plans t ON t.id = e.trip_id


        AND t.destination_code = #{destinationCode}


        AND t.end_date >= #{dateFrom}


        AND t.start_date <= #{dateTo}


        AND (

            t.tags LIKE ('%"' || #{tag} || '"%')

        )


 ORDER BY e.updated_at DESC, e.id DESC
